<script lang="ts">
import {createRequestGate} from './requestGate.js';
import {onDestroy} from 'svelte';
import {keycapLabel} from './mappingPresentation.js';
import {filterMappingOptions} from './mappingSearch.js';
const requests=createRequestGate();let loadedId='';
type Shortcut={keyCode:number;modifiers:number[]};
export interface MappingChange{buttonId:string;action:string;expectedState:string;shortcut?:Shortcut;layer?:string}
export interface MappingSnapshot{deviceId:string;model:string;sampledAt:number;stateToken:string;buttons:{id:string;label:string;currentAction:string|null;currentLabel:string;editable:boolean;rawHex?:string;shortcut?:Shortcut}[];actions:{id:string;label:string;category?:string}[];unsupported:{id:string;reason:string}[];keyboardOptions?:{label:string;value:number;category:string}[];shortcutSupport?:{maxModifiers:number;maxActions:number;keyCodeMin:number;keyCodeMax:number;modifiers:number[]}}
let{deviceId,load,apply,sample=false,keyboard=false}:{deviceId:string|null;load:(id:string,layer?:string)=>Promise<MappingSnapshot>;apply:(id:string,change:MappingChange)=>Promise<MappingSnapshot>;sample?:boolean;keyboard?:boolean}=$props();
let layer=$state('Default');let keyFilter=$state('');
let group=$state('base');
const groups=$derived(keyboard?[{id:'base',label:'基础按键'},{id:'mouse',label:'鼠标功能'},{id:'media',label:'媒体功能'},{id:'extended',label:'扩展功能'},{id:'macro',label:'快捷指令录制'}]:[{id:'mouse',label:'鼠标功能'},{id:'keyboard',label:'键盘按键'},{id:'shortcut',label:'组合快捷键'},{id:'dpi',label:'DPI 功能'},{id:'wheel',label:'滚轮功能'},{id:'media',label:'媒体功能'},{id:'profile',label:'配置切换'},{id:'special',label:'特殊功能'}]);
const rows=[['Esc','F1','F2','F3','F4','F5','F6','F7','F8','F9','F10','F11','F12','Insert','Delete'],['backquote','one','two','three','four','five','six','seven','eight','nine','zero','transverse','equal','Backspace','Home'],['Tab','Q','W','E','R','T','Y','U','I','O','P','left_bracket','right_bracket','backslash','PgUp'],['Caps','A','S','D','F','G','H','J','K','L','semicolon','singlequotes','Enter','PgDn'],['Left_Shift','Z','X','C','V','B','N','M','comma','dot','slash','Right_Shift','up'],['Left_Ctrl','Left_Win','Left_Alt','Space','Fn','Right_Ctrl','left','down','right']];
const widths:Record<string,number>={Tab:60,backslash:63,Caps:72,Enter:98,Left_Shift:92,Right_Shift:78,Left_Ctrl:50,Left_Win:50,Left_Alt:50,Space:286,Fn:54,Right_Ctrl:54,Backspace:82};
const keyLabels:Record<string,string>={backquote:'` ~',one:'1 !',two:'2 @',three:'3 #',four:'4 $',five:'5 %',six:'6 ^',seven:'7 &',eight:'8 *',nine:'9 (',zero:'0 )',transverse:'- _',equal:'= +',left_bracket:'[ {',right_bracket:'] }',backslash:'\\ |',semicolon:'; :',singlequotes:"' \"",comma:', <',dot:'. >',slash:'/ ?',Left_Shift:'Shift',Right_Shift:'Shift',Left_Ctrl:'Ctrl',Right_Ctrl:'Ctrl',Left_Win:'Win',Left_Alt:'Alt',Space:'Space',left:'←',right:'→',up:'↑',down:'↓'};
const keyLabel=(id:string)=>keyLabels[id]||id;
const currentKeyLabel=(id:string)=>keycapLabel(id,snapshot?.buttons.find(button=>button.id===id)?.currentAction,keyLabel);
const actionLabel=(item:{id:string;label:string})=>item.id.startsWith('key:')?keyLabel(item.id.slice(4)):item.label;
const category=(a:{id:string;category?:string})=>a.category|| (a.id==='shortcut'||a.id.startsWith('key:')?'base':a.id.startsWith('dpi')?'dpi':a.id.startsWith('media:')?'media':a.id.startsWith('mouse:')||['disabled','leftClick','rightClick','middleClick','back','forward','wheelUp','wheelDown'].includes(a.id)?'mouse':'extended');
const mouseButtons=[{id:'left',label:'左键',x:15,y:22},{id:'right',label:'右键',x:69,y:22},{id:'center',label:'中键',x:68,y:46},{id:'side1',label:'侧键 1',x:6,y:54},{id:'side2',label:'侧键 2',x:6,y:74},{id:'bottom',label:'DPI 按键',x:64,y:82}];
let snapshot=$state<MappingSnapshot|null>(null);let selected=$state('');let action=$state('');let busy=$state(false);let error=$state('');let success=$state('');let confirmed=$state(false);
const groupActions=$derived(filterMappingOptions(snapshot?.actions.filter(a=>category(a)===group)??[],keyFilter));
const keyboardOptions=$derived(filterMappingOptions(snapshot?.keyboardOptions??[],keyFilter));
const hasVisibleActions=$derived(groupActions.length>0||(!keyboard&&group==='keyboard'&&keyboardOptions.length>0));
let shortcutKey=$state(4);let modifiers=$state<number[]>([]);
const button=$derived(snapshot?.buttons.find(b=>b.id===selected));const dirty=$derived(!!button&&action!==''&&(action!==button.currentAction||(action==='shortcut'&&(shortcutKey!==button.shortcut?.keyCode||JSON.stringify([...modifiers].sort())!==JSON.stringify([...(button.shortcut?.modifiers||[])].sort())))));
const shortcutValid=$derived(action!=='shortcut'||!!snapshot?.shortcutSupport&&modifiers.length<=snapshot.shortcutSupport.maxModifiers&&(shortcutKey<224||modifiers.length===0)&&(snapshot.keyboardOptions?.length?snapshot.keyboardOptions.some(item=>item.value===shortcutKey):shortcutKey>=snapshot.shortcutSupport.keyCodeMin&&shortcutKey<=snapshot.shortcutSupport.keyCodeMax));
const keyName=(code:number)=>snapshot?.keyboardOptions?.find(item=>item.value===code)?.label||(code<30?String.fromCharCode(65+code-4):code===39?'0':code<=39?String(code-29):`HID ${code}`);
const modifierName=(code:number)=>({1:'左 Ctrl',2:'左 Shift',4:'左 Alt',8:'左 Win',16:'右 Ctrl',32:'右 Shift',64:'右 Alt',128:'右 Win'}[code]||String(code));
function resetShortcut(){const value=snapshot?.buttons.find(b=>b.id===selected)?.shortcut;shortcutKey=value?.keyCode??4;modifiers=[...(value?.modifiers||[])];}
export function hasUnsavedChanges(){return dirty||busy;}export function isOperationPending(){return busy;}
const text=(e:unknown)=>e&&typeof e==='object'&&'message'in e?String(e.message):String(e);
function accept(value:MappingSnapshot){if(!snapshot)group=keyboard?'base':'mouse';snapshot=value;selected=value.buttons.some(b=>b.id===selected)?selected:value.buttons[0]?.id||'';action=value.buttons.find(b=>b.id===selected)?.currentAction||'';resetShortcut();confirmed=true;}
async function read(){if(!deviceId)return;const current=requests.begin();busy=true;error='';success='';try{const value=await load(deviceId,layer);if(current())accept(value);}catch(e){if(current()){error=text(e);confirmed=false;}}finally{if(current())busy=false;}}
function changeLayer(e:Event){const input=e.currentTarget as HTMLSelectElement;if(dirty){input.value=layer;error='请先撤回或应用当前按键的预览，再切换层。';return;}layer=input.value;selected='';void read();}
function choose(id:string){if(dirty){error='请先撤回或应用当前按钮的预览，再切换按钮。';return;}selected=id;action=snapshot?.buttons.find(b=>b.id===id)?.currentAction||'';resetShortcut();error='';success='';}
async function submit(){if(!deviceId||busy||!snapshot||!button?.editable||!dirty||!confirmed||!shortcutValid)return;const current=requests.begin();busy=true;error='';success='';try{const value=await apply(deviceId,{buttonId:selected,action,expectedState:snapshot.stateToken,...(keyboard?{layer}:{}),...(action==='shortcut'?{shortcut:{keyCode:shortcutKey,modifiers:[...modifiers]}}:{})});if(!current())return;accept(value);success=sample?'样本已更新，仅验证界面逻辑。':'映射已写入并读回确认。';}catch(e){if(!current())return;error=`${text(e)}。请重新读取核对。`;confirmed=false;}finally{if(current())busy=false;}}
$effect(()=>{if(loadedId!==(deviceId||'')){loadedId=deviceId||'';requests.invalidate();snapshot=null;selected='';action='';confirmed=false;busy=false;if(deviceId)void read();}});
onDestroy(()=>requests.invalidate());
</script>
<!-- Primary: physical target and target action. Secondary: current mapping; tertiary: protocol status.
     Geometry follows official KX75 layout; spacing uses 4/8/16/24 and existing theme tokens. -->
<section class="mapping-panel" class:keyboard={keyboard} aria-label="按键映射设置">
{#if sample}<p class="mapping-sample" role="status">样本预览 · 不连接设备、不代表当前真实映射</p>{/if}
<div class="mapping-heading"><h3>按键配置</h3><p>点击设备上的按键，再选择要分配的功能。</p></div>
<div class="mapping-editor">
<div class="physical-device">
{#if keyboard}
  <div class="keyboard-scroll" role="region" aria-label="KX75 物理按键布局，可横向滚动"><div class="physical-keyboard">{#each rows as row,index}<div class="key-row" class:function-row={index===0}>{#each row as id}<button class="physical-key" class:selected={selected===id} class:readonly={!snapshot?.buttons.find(b=>b.id===id)?.editable} style={`width:${widths[id]||42}px;${index===0&&['F1','F5','F9','Insert'].includes(id)?'margin-left:12px;':''}${id==='left'?'margin-left:28px;':''}`} aria-label={`选择 ${keyLabel(id)}`} aria-pressed={selected===id} title={snapshot?.buttons.find(b=>b.id===id)?.currentLabel||'尚未读取'} disabled={busy||!snapshot?.buttons.some(b=>b.id===id)} onclick={()=>choose(id)}>{currentKeyLabel(id)}</button>{/each}</div>{/each}</div></div>
  <div class="layer-switch"><label for="mapping-layer">配置层</label><select id="mapping-layer" value={layer} onchange={changeLayer} disabled={busy||!snapshot}><option>Default</option><option>Fn</option><option>Fn2</option></select><span>{button?`当前选择：${keyLabel(button.id)}`:'等待设备读数'}</span></div>
{:else}
  <div class="mouse-stage" aria-label="ATK F1 物理按钮布局"><svg viewBox="0 0 260 340" aria-hidden="true"><defs><linearGradient id="mouse-shell" x1="0" x2="1" y1="0" y2="1"><stop stop-color="var(--muted)"/><stop offset="1" stop-color="var(--ink)"/></linearGradient></defs><path d="M130 24C76 24 52 54 50 118L47 225C48 284 77 316 130 319C183 316 212 284 213 225L210 118C208 54 184 24 130 24Z" fill="url(#mouse-shell)"/><path d="M130 25V151M51 151Q130 170 209 151" fill="none" stroke="var(--surface)" stroke-opacity=".3"/><rect x="119" y="59" width="22" height="48" rx="10" fill="var(--surface)" opacity=".65"/><path d="M120 64V101M130 64V101M138 64V101" stroke="var(--ink)" opacity=".6"/><text x="130" y="266" text-anchor="middle" fill="var(--surface)" font-size="20" font-weight="600">ATK</text></svg>
  {#each mouseButtons as point}<button class="mouse-callout" class:selected={selected===point.id} style={`left:${point.x}%;top:${point.y}%`} disabled={busy||!snapshot?.buttons.some(b=>b.id===point.id)} aria-pressed={selected===point.id} onclick={()=>choose(point.id)}><span>{point.label}</span><strong>{snapshot?.buttons.find(b=>b.id===point.id)?.currentLabel||'尚未读取'}</strong></button>{/each}</div>
{/if}
</div>
<div class="assignment-panel">
{#if button}<div class="mapping-current"><span>{keyboard?keyLabel(button.id):button.label}</span><strong>{button.currentLabel}</strong>{#if !button.editable}<small>当前原始映射只读，保留设备原值。</small>{/if}</div>{/if}
<div class="action-tabs" aria-label="功能分组">{#each groups as item}<button class:active={group===item.id} aria-pressed={group===item.id} onclick={()=>group=item.id}>{item.label}</button>{/each}</div>
<input class="action-search" aria-label="搜索目标功能" placeholder="搜索功能名称" bind:value={keyFilter} disabled={!snapshot}/>
<div class="action-grid">{#each groupActions as item}<button class:selected={action===item.id} aria-pressed={action===item.id} disabled={busy||!button?.editable||!confirmed} onclick={()=>action=item.id}>{actionLabel(item)}</button>{/each}</div>
{#if !keyboard&&group==='keyboard'&&keyboardOptions.length}<div class="action-grid">{#each keyboardOptions as key}<button class:selected={action==='shortcut'&&shortcutKey===key.value&&modifiers.length===0} disabled={busy||!button?.editable||!confirmed} onclick={()=>{action='shortcut';shortcutKey=key.value;modifiers=[];}}>{key.label}</button>{/each}</div>{/if}
{#if !hasVisibleActions}<div class="category-empty" role="status"><strong>{keyFilter.trim()&&snapshot?'没有匹配的功能':groups.find(g=>g.id===group)?.label}</strong><p>{!snapshot?'连接设备并读取后显示可用功能。':keyFilter.trim()?'尝试其他名称，或清空搜索查看此分组。':group==='macro'?'KX75 宏区协议仍待核实，暂不可分配快捷指令。':'此分组的设备编码尚待核实，暂不可应用。'}</p>{#if keyFilter.trim()&&snapshot}<button class="secondary" onclick={()=>keyFilter=''}>清空搜索</button>{/if}</div>{/if}
{#if action==='shortcut'&&snapshot?.shortcutSupport}<div class="shortcut-editor"><label for="shortcut-key">主键</label><select id="shortcut-key" value={shortcutKey} onchange={e=>{shortcutKey=Number(e.currentTarget.value);if(shortcutKey>=224)modifiers=[];}} disabled={busy||!button?.editable}>{#each snapshot.keyboardOptions??Array.from({length:snapshot.shortcutSupport.keyCodeMax-snapshot.shortcutSupport.keyCodeMin+1},(_,i)=>({value:i+(snapshot?.shortcutSupport?.keyCodeMin??4),label:keyName(i+(snapshot?.shortcutSupport?.keyCodeMin??4))})) as item}<option value={item.value}>{item.label}</option>{/each}</select><div class="modifier-options">{#each snapshot.shortcutSupport.modifiers as code}<label><input type="checkbox" checked={modifiers.includes(code)} disabled={busy||!button?.editable||(!modifiers.includes(code)&&modifiers.length>=snapshot.shortcutSupport.maxModifiers)} onchange={e=>{modifiers=e.currentTarget.checked?[...modifiers,code]:modifiers.filter(v=>v!==code);}}/>{modifierName(code)}</label>{/each}</div><p class="mapping-note">最多 {snapshot.shortcutSupport.maxModifiers} 个修饰键与 1 个主键。</p></div>{/if}
{#if dirty&&button}<div class="change-preview"><strong>待应用到 {keyboard?keyLabel(button.id):button.label}</strong><p>{button.currentLabel} → {snapshot?.actions.find(a=>a.id===action)?.label||action}{action==='shortcut'?' · '+[...modifiers.map(modifierName),keyName(shortcutKey)].join(' + '):''}</p></div>{/if}
</div></div>
{#if !deviceId}<p class="mapping-note">请连接受支持的接收器后读取按键。</p>{:else if busy&&!snapshot}<p role="status" class="mapping-note">正在读取当前映射…</p>{/if}
{#if error}<p class="message error" role="alert">{error}</p>{/if}{#if success}<p class="settings-success" role="status">{success}</p>{/if}
<div class="settings-actions"><span role="status">{busy?'正在与设备通信…':!confirmed&&dirty?'请先撤回预览再重新读取核对。':dirty?'当前按键有待应用的预览':snapshot?.sampledAt?`最近读取 ${new Date(snapshot.sampledAt).toLocaleTimeString('zh-CN')}`:'未读取当前映射'}</span><button class="secondary" disabled={!deviceId||busy||dirty} onclick={read}>重新读取</button><button class="secondary" disabled={!dirty||busy} onclick={()=>{if(snapshot){const wasConfirmed=confirmed;accept(snapshot);confirmed=wasConfirmed;}success='';}}>撤回预览</button><button class="primary" disabled={!dirty||busy||!confirmed||!button?.editable||!shortcutValid} onclick={submit}>{busy?'等待确认…':sample?'应用到样本':'应用到设备'}</button></div>
<details class="mapping-details"><summary>功能支持状态</summary>{#each snapshot?.unsupported??[] as item}<p>{item.reason}</p>{/each}{#if !snapshot?.shortcutSupport}<p>任意自定义组合键编码仍待核实，已核实预设可在扩展功能中选择。</p>{/if}</details>
</section>
<style>
/* §2.1 / §3.6: physical target, confirmed mapping, target action, then apply. */
.mapping-panel{min-width:0}.mapping-heading{margin:0 0 24px}.mapping-heading h3{font-size:16px;font-weight:600;margin:0 0 8px}.mapping-heading p,.mapping-note{font-size:12px;line-height:1.65;color:var(--muted);margin:0 0 16px}.mapping-editor{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px}.physical-device,.assignment-panel{min-width:0}.mouse-stage{position:relative;min-height:400px;background:var(--control);border:1px solid var(--quiet-line);border-radius:12px}.mouse-stage svg{position:absolute;height:304px;width:232px;left:50%;top:50%;transform:translate(-50%,-50%)}.mouse-callout{position:absolute;display:flex;flex-direction:column;gap:4px;align-items:flex-start;max-width:128px;padding:8px 12px;background:var(--glass-panel,var(--surface));color:var(--ink);border:1px solid var(--line);border-radius:8px;font-size:12px;z-index:1;overflow-wrap:anywhere;text-align:left}.mouse-callout span{color:var(--muted);font-size:12px}.mouse-callout strong{font-weight:500}.mouse-callout.selected{border-color:var(--accent);outline:1px solid var(--accent)}.mapping-current{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:16px;margin-bottom:16px;background:var(--control);border-radius:12px}.mapping-current>span{font-size:12px;color:var(--muted)}.mapping-current strong{font-size:14px;font-weight:600}.mapping-current small{display:block;width:100%;font-size:12px;color:var(--muted);line-height:1.65}.action-tabs{display:flex;gap:4px;flex-wrap:wrap;margin-bottom:16px}.action-tabs button{border:1px solid transparent;background:transparent;padding:8px;font:inherit;font-size:12px;color:var(--muted);border-radius:8px;min-height:36px}.action-tabs button.active{background:var(--control);border-color:var(--quiet-line);color:var(--accent);font-weight:600}.action-search{width:100%;padding:8px 12px;background:var(--control);border:1px solid var(--line);border-radius:8px;color:var(--ink);font:inherit;font-size:12px;margin-bottom:16px;min-height:36px}.action-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;max-height:272px;overflow:auto}.action-grid:empty{display:none}.action-grid button{min-width:0;min-height:40px;padding:8px;background:var(--control);border:1px solid var(--quiet-line);border-radius:8px;color:var(--ink);font:inherit;font-size:12px;overflow-wrap:anywhere}.action-grid button.selected{border-color:var(--accent);color:var(--accent);background:var(--glass-chrome,var(--control))}.category-empty{padding:24px 16px;border:1px dashed var(--line);border-radius:12px;font-size:13px}.category-empty strong{font-weight:600}.category-empty p{font-size:12px;color:var(--muted);line-height:1.65;margin:8px 0 0}.category-empty button{margin-top:16px}.keyboard .mapping-editor{display:block}.keyboard-scroll{overflow:auto;max-width:100%;background:var(--control);border:1px solid var(--quiet-line);border-radius:12px;padding:16px;overscroll-behavior-x:contain}.physical-keyboard{width:max-content;margin:0 auto}.key-row{display:flex;gap:4px;margin-top:4px}.key-row:first-child{margin-top:0}.key-row.function-row{margin-bottom:12px}.physical-key{height:32px;flex-shrink:0;min-width:0;padding:0 2px;border:1px solid var(--quiet-line);border-radius:4px;background:var(--glass-panel,var(--surface));color:var(--ink);font-size:12px}.physical-key.selected{border-color:var(--accent);outline:1px solid var(--accent);color:var(--accent)}.physical-key.readonly{color:var(--muted)}.layer-switch{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin:16px 0 24px;font-size:12px}.layer-switch label{font-weight:500}.layer-switch span{color:var(--muted)}.layer-switch select,.shortcut-editor select{padding:8px 12px;min-height:36px;border:1px solid var(--line);border-radius:8px;background:var(--control);color:var(--ink);font:inherit;font-size:12px}.keyboard .action-grid{grid-template-columns:repeat(8,minmax(0,1fr));max-height:232px}.shortcut-editor{padding-top:16px;font-size:12px}.shortcut-editor>label{margin-right:12px}.modifier-options{display:flex;flex-wrap:wrap;gap:12px;margin:16px 0}.modifier-options label{display:flex;align-items:center;gap:8px}.modifier-options input{accent-color:var(--accent)}.mapping-details{margin-top:16px;border-top:1px solid var(--quiet-line);padding-top:12px;font-size:12px;color:var(--muted);line-height:1.65}.mapping-details summary{cursor:pointer;color:var(--ink)}.mapping-details p{margin:12px 0 0}.mapping-sample{font-size:12px;line-height:1.65;color:var(--warning);background:var(--warning-soft);border-radius:8px;padding:12px 16px;margin:0 0 16px}
@media(max-width:850px){.mapping-editor{grid-template-columns:1fr}.mouse-stage{min-height:352px}.mouse-stage svg{height:280px}.keyboard .action-grid{grid-template-columns:repeat(6,minmax(0,1fr))}}@media(max-width:450px){.keyboard .action-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.action-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.mouse-callout{max-width:104px;padding:8px}.mouse-stage{min-height:336px}.keyboard-scroll{padding:12px}.mapping-heading{margin-bottom:16px}.mapping-heading p{margin-bottom:0}}
</style>
